import assert from 'node:assert/strict';
import fs from 'node:fs';
import YAML from './node_modules/yaml/dist/index.js';
const paths = process.argv.slice(1);
assert.deepEqual(paths, ['.github/workflows/host-emulated-acceptance.yml', '.github/workflows/electron-packaged-ci.yml']);
for (const path of paths) {
  const info = fs.lstatSync(path);
  assert.ok(info.isFile() && !info.isSymbolicLink() && info.size > 0 && info.size <= 131072, path);
  const descriptor = fs.openSync(path, 'r');
  let bytes;
  try {
    const buffer = Buffer.alloc(131072);
    const length = fs.readSync(descriptor, buffer, 0, buffer.byteLength, 0);
    assert.equal(length, info.size, path);
    bytes = buffer.subarray(0, length);
  } finally {
    fs.closeSync(descriptor);
  }
  const source = bytes.toString('utf8');
  assert.equal(Buffer.byteLength(source), bytes.byteLength, path);
  const documents = YAML.parseAllDocuments(source, { version: '1.2', strict: true, uniqueKeys: true, prettyErrors: false });
  assert.equal(documents.length, 1, path);
  const document = documents[0];
  assert.equal(document.errors.length, 0, path);
  const value = document.toJS({ maxAliasCount: 100 });
  assert.ok(value !== null && typeof value === 'object' && !Array.isArray(value), path);
  console.log(JSON.stringify({ path, bytes: info.size, documents: 1, errors: 0, warnings: document.warnings.length }));
}

